import{_ as t,o as l,c as n,a2 as i}from"./chunks/framework.DpXDHk3d.js";const u=JSON.parse('{"title":"6.2 电缆的种类与选用","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/06-chapter-6-dao-xian-dian-lan-yu-di-ya-xian-lu/6-2-dian-lan-de-zhong-lei-yu-xuan-yong.md","filePath":"electrician/low-voltage-electrician/06-chapter-6-dao-xian-dian-lan-yu-di-ya-xian-lu/6-2-dian-lan-de-zhong-lei-yu-xuan-yong.md","lastUpdated":1793095197000}'),o={name:"electrician/low-voltage-electrician/06-chapter-6-dao-xian-dian-lan-yu-di-ya-xian-lu/6-2-dian-lan-de-zhong-lei-yu-xuan-yong.md"};function r(s,a,e,d,g,h){return l(),n("div",null,[...a[0]||(a[0]=[i(`<h1 id="_6-2-电缆的种类与选用" tabindex="-1">6.2 电缆的种类与选用 <a class="header-anchor" href="#_6-2-电缆的种类与选用" aria-label="Permalink to &quot;6.2 电缆的种类与选用&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>电缆比导线&quot;豪华&quot;——里面多了一层又一层保护,能应付地下、潮湿、受力的环境。这一节认识电缆的结构、型号(VV、YJV)和选用原则。</p><h2 id="一、电缆的结构" tabindex="-1">一、电缆的结构 <a class="header-anchor" href="#一、电缆的结构" aria-label="Permalink to &quot;一、电缆的结构&quot;">​</a></h2><p>一根电力电缆,从里到外一般是:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────┐</span></span>
<span class="line"><span>│  线芯(导体)           │  导电部分,一芯或多芯</span></span>
<span class="line"><span>│  绝缘层               │  芯线外面的绝缘</span></span>
<span class="line"><span>│  护套层(外护层)       │  保护绝缘和线芯</span></span>
<span class="line"><span>│  铠装(部分电缆)       │  钢带等,抗机械损伤</span></span>
<span class="line"><span>└──────────────────────┘</span></span></code></pre></div><ul><li><strong>线芯</strong>:导电主体(铜或铝),可单芯、可多芯;</li><li><strong>绝缘层</strong>:保证芯线之间、芯线与地之间的绝缘;</li><li><strong>护套层</strong>:机械保护,防止潮气、腐蚀;</li><li><strong>铠装层</strong>(部分):增加抗压、抗拉能力,用于直埋敷设。</li></ul><h2 id="二、电缆的型号" tabindex="-1">二、电缆的型号 <a class="header-anchor" href="#二、电缆的型号" aria-label="Permalink to &quot;二、电缆的型号&quot;">​</a></h2><p>常见低压电力电缆型号:</p><table tabindex="0"><thead><tr><th>型号</th><th>含义</th></tr></thead><tbody><tr><td><strong>VV</strong></td><td>铜芯聚氯乙烯绝缘聚氯乙烯护套电缆</td></tr><tr><td><strong>VLV</strong></td><td>铝芯聚氯乙烯绝缘聚氯乙烯护套电缆</td></tr><tr><td><strong>YJV</strong></td><td>铜芯<strong>交联聚乙烯</strong>绝缘聚乙烯护套电缆(现代常用,耐温高)</td></tr><tr><td><strong>YJLV</strong></td><td>铝芯交联聚乙烯绝缘电缆</td></tr><tr><td>加数字</td><td>如 VV22、YJV22,<strong>22 表示带钢带铠装</strong>(可直埋)</td></tr></tbody></table><blockquote><p>💡 解读:字母规律和导线类似——<strong>V=聚氯乙烯,YJ=交联聚乙烯,没有 L 是铜芯</strong>;末尾数字 22/23 表示铠装层。</p></blockquote><h2 id="三、电缆的选用原则" tabindex="-1">三、电缆的选用原则 <a class="header-anchor" href="#三、电缆的选用原则" aria-label="Permalink to &quot;三、电缆的选用原则&quot;">​</a></h2><ol><li><strong>按电压等级</strong>:电缆额定电压 ≥ 线路工作电压(低压电缆 0.6/1 kV 等);</li><li><strong>按敷设方式</strong>: <ul><li><strong>直埋地下</strong> → 选<strong>铠装电缆</strong>(VV22、YJV22),能抗压;</li><li>穿管、桥架敷设 → 普通电缆即可;</li></ul></li><li><strong>按环境</strong>: <ul><li>潮湿、腐蚀环境 → 选防水防腐型护套;</li><li>高温环境 → 选交联聚乙烯(YJV)等耐热型号;</li></ul></li><li><strong>按载流量</strong>:电缆截面要满足负载电流(见 6.3 节);</li><li><strong>按芯数</strong>:单相负荷选两芯或三芯,三相选四芯/五芯(含中性线、保护线)。</li></ol><h2 id="四、电缆敷设的安全要求" tabindex="-1">四、电缆敷设的安全要求 <a class="header-anchor" href="#四、电缆敷设的安全要求" aria-label="Permalink to &quot;四、电缆敷设的安全要求&quot;">​</a></h2><ul><li>电缆埋地深度要足够(一般 ≥ 0.7 m),上面铺设保护盖板;</li><li>电缆与其他管道(燃气管、热力管)要保证间距;</li><li>电缆两端和接头处要<strong>封堵防潮</strong>,接头工艺要规范;</li><li>电缆线路要设标识,便于维护和防止误挖。</li></ul><h2 id="五、考点提示" tabindex="-1">五、考点提示 <a class="header-anchor" href="#五、考点提示" aria-label="Permalink to &quot;五、考点提示&quot;">​</a></h2><ul><li>✅ 电缆结构:线芯、绝缘层、护套层(部分带铠装)。</li><li>✅ VV=铜芯塑料绝缘塑料护套,YJV=交联聚乙烯(耐高温更好)。</li><li>✅ 直埋地下选<strong>铠装电缆</strong>(型号带 22)。</li><li>⚠️ 易混点:型号中 V 和 YJ 是绝缘材料,末尾数字表示铠装/外护套。</li></ul><h2 id="六、本节小结" tabindex="-1">六、本节小结 <a class="header-anchor" href="#六、本节小结" aria-label="Permalink to &quot;六、本节小结&quot;">​</a></h2><ul><li>电缆 = 线芯 + 绝缘 + 护套(可选铠装)。</li><li>VV 是 PVC 电缆,YJV 是交联聚乙烯电缆,22 表示铠装。</li><li>直埋要铠装、高温选交联、截面按载流量。</li></ul><h2 id="七、自测练习" tabindex="-1">七、自测练习 <a class="header-anchor" href="#七、自测练习" aria-label="Permalink to &quot;七、自测练习&quot;">​</a></h2><ol><li>(单选)电缆型号 VV 表示()。 A. 铝芯橡皮电缆　B. 铜芯聚氯乙烯绝缘聚氯乙烯护套电缆　C. 交联聚乙烯电缆　D. 裸电缆</li><li>(单选)YJV 电缆中的 YJ 表示()。 A. 聚氯乙烯　B. 交联聚乙烯　C. 橡胶　D. 聚乙烯</li><li>(判断)直埋地下的电缆应选用铠装电缆。( )</li><li>(判断)电缆型号带&quot;22&quot;表示带钢带铠装。( )</li><li>(单选)高温场所敷设电缆,应优先选用()。 A. VV　B. YJV　C. 橡皮线　D. 裸导线</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>B</strong>。VV = 铜芯聚氯乙烯绝缘聚氯乙烯护套电缆。</li><li><strong>B</strong>。YJ 表示交联聚乙烯绝缘。</li><li><strong>√</strong>。直埋需要抗压,选铠装电缆。</li><li><strong>√</strong>。22 表示带钢带铠装。</li><li><strong>B</strong>。交联聚乙烯(YJV)耐温更高。</li></ol></details>`,22)])])}const p=t(o,[["render",r]]);export{u as __pageData,p as default};
